import{i as e,r as t,s as n,t as r}from"./app-CSY-Kgjv.js";var i=JSON.parse(`{"path":"/org/api.html","title":"API","lang":"zh-CN","frontmatter":{"description":"API 1. 定义与职责 API 网关层位于 接入层之后、业务服务之前，是所有业务 API 的统一入口。 它不承载核心业务逻辑，而是负责 流量治理、安全控制、协议适配和可观测性。 核心职责： 统一 API 入口，屏蔽后端微服务复杂性 流量控制（限流 / 熔断 / 降级） 认证与鉴权 协议与数据格式转换 灰度发布与版本管理 API 级别监控与审计 2. ...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"API\\",\\"image\\":[\\"\\"],\\"dateModified\\":\\"2026-03-11T05:49:26.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"DeeLMind\\",\\"url\\":\\"https://deelmind.com\\"}]}"],["meta",{"property":"og:url","content":"https://deelmind.com/org/api.html"}],["meta",{"property":"og:site_name","content":"極客方舟"}],["meta",{"property":"og:title","content":"API"}],["meta",{"property":"og:description","content":"API 1. 定义与职责 API 网关层位于 接入层之后、业务服务之前，是所有业务 API 的统一入口。 它不承载核心业务逻辑，而是负责 流量治理、安全控制、协议适配和可观测性。 核心职责： 统一 API 入口，屏蔽后端微服务复杂性 流量控制（限流 / 熔断 / 降级） 认证与鉴权 协议与数据格式转换 灰度发布与版本管理 API 级别监控与审计 2. ..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-03-11T05:49:26.000Z"}],["meta",{"property":"article:modified_time","content":"2026-03-11T05:49:26.000Z"}]]},"git":{"createdTime":1769836766000,"updatedTime":1773208166000,"contributors":[{"name":"DeeLMind","username":"DeeLMind","email":"deelmind@gmail.com","commits":2,"url":"https://github.com/DeeLMind"}]},"readingTime":{"minutes":3.48,"words":1043},"filePathRelative":"org/api.md","autoDesc":true}`),a={name:`api.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="api" tabindex="-1"><a class="header-anchor" href="#api"><span>API</span></a></h1><h2 id="_1-定义与职责" tabindex="-1"><a class="header-anchor" href="#_1-定义与职责"><span>1. 定义与职责</span></a></h2><p>API 网关层位于 <strong>接入层之后、业务服务之前</strong>，是所有业务 API 的统一入口。<br> 它不承载核心业务逻辑，而是负责 <strong>流量治理、安全控制、协议适配和可观测性</strong>。</p><p>核心职责：</p><ol><li>统一 API 入口，屏蔽后端微服务复杂性</li><li>流量控制（限流 / 熔断 / 降级）</li><li>认证与鉴权</li><li>协议与数据格式转换</li><li>灰度发布与版本管理</li><li>API 级别监控与审计</li></ol><hr><h2 id="_2-api-网关在整体架构中的位置" tabindex="-1"><a class="header-anchor" href="#_2-api-网关在整体架构中的位置"><span>2. API 网关在整体架构中的位置</span></a></h2><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>接入层 (DNS / CDN / WAF / LB)</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>▼</span></span>
<span class="line"><span>┌─────────────────────────┐</span></span>
<span class="line"><span>│ API 网关层 │</span></span>
<span class="line"><span>│ 统一入口 / 流量治理 │</span></span>
<span class="line"><span>└─────────────────────────┘</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>▼</span></span>
<span class="line"><span>应用层（微服务 / RPC / gRPC）</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="_3-核心功能模块" tabindex="-1"><a class="header-anchor" href="#_3-核心功能模块"><span>3. 核心功能模块</span></a></h2><h3 id="_3-1-api-路由与聚合" tabindex="-1"><a class="header-anchor" href="#_3-1-api-路由与聚合"><span>3.1 API 路由与聚合</span></a></h3><p><strong>作用</strong>：<br> 将外部请求路由到正确的后端服务，必要时对多个服务结果进行聚合。</p><p><strong>能力</strong>：</p><ul><li>路径 / Host / Header 路由</li><li>API 版本管理（v1 / v2）</li><li>多服务结果聚合（BFF 模式）</li></ul><p><strong>设计要点</strong>：</p><ul><li>网关只做“轻逻辑”，避免业务侵入</li><li>聚合逻辑尽量简单，复杂逻辑下沉到应用层</li></ul><hr><h3 id="_3-2-认证与鉴权-authn-authz" tabindex="-1"><a class="header-anchor" href="#_3-2-认证与鉴权-authn-authz"><span>3.2 认证与鉴权（AuthN / AuthZ）</span></a></h3><p><strong>作用</strong>：<br> 统一处理身份认证和权限校验，避免每个服务重复实现。</p><p><strong>常见方式</strong>：</p><ul><li>OAuth2</li><li>JWT / Access Token</li><li>API Key</li><li>mTLS（服务间）</li></ul><p><strong>设计要点</strong>：</p><ul><li>鉴权在网关完成，服务默认信任网关</li><li>Token 校验失败直接在网关拦截</li><li>权限模型要与业务解耦</li></ul><hr><h3 id="_3-3-限流-rate-limiting" tabindex="-1"><a class="header-anchor" href="#_3-3-限流-rate-limiting"><span>3.3 限流（Rate Limiting）</span></a></h3><p><strong>作用</strong>：<br> 防止流量洪峰、恶意请求或雪崩效应。</p><p><strong>限流维度</strong>：</p><ul><li>IP</li><li>用户 ID</li><li>API Key</li><li>接口级别</li></ul><p><strong>常见算法</strong>：</p><ul><li>Token Bucket</li><li>Leaky Bucket</li><li>固定窗口 / 滑动窗口</li></ul><p><strong>设计要点</strong>：</p><ul><li>区分 <strong>保护系统</strong> 和 <strong>限制用户</strong></li><li>限流策略可动态调整</li><li>支持不同 API 不同限额</li></ul><hr><h3 id="_3-4-熔断与降级" tabindex="-1"><a class="header-anchor" href="#_3-4-熔断与降级"><span>3.4 熔断与降级</span></a></h3><p><strong>作用</strong>：<br> 当下游服务异常时，防止请求持续放大故障。</p><p><strong>能力</strong>：</p><ul><li>熔断（Circuit Breaker）</li><li>快速失败</li><li>服务降级（返回兜底数据）</li></ul><p><strong>设计要点</strong>：</p><ul><li>熔断是“止血”，不是“修复”</li><li>降级返回应可被客户端识别</li><li>熔断策略要基于真实指标（错误率、延迟）</li></ul><hr><h3 id="_3-5-协议与数据转换" tabindex="-1"><a class="header-anchor" href="#_3-5-协议与数据转换"><span>3.5 协议与数据转换</span></a></h3><p><strong>作用</strong>：<br> 解耦客户端与后端服务的通信方式。</p><p><strong>常见场景</strong>：</p><ul><li>HTTP → gRPC</li><li>REST → RPC</li><li>JSON → Protobuf</li><li>Header / Body 结构转换</li></ul><p><strong>设计要点</strong>：</p><ul><li>网关适配客户端多样性</li><li>后端服务内部通信保持高效协议</li></ul><hr><h3 id="_3-6-灰度发布与流量切分" tabindex="-1"><a class="header-anchor" href="#_3-6-灰度发布与流量切分"><span>3.6 灰度发布与流量切分</span></a></h3><p><strong>作用</strong>：<br> 支持无感知发布、风险控制。</p><p><strong>能力</strong>：</p><ul><li>按比例分流（5% / 10%）</li><li>按用户 / Header 分流</li><li>A/B Test</li></ul><p><strong>设计要点</strong>：</p><ul><li>与 CI/CD / 配置中心联动</li><li>支持快速回滚</li><li>流量规则必须可观测</li></ul><hr><h3 id="_3-7-日志、监控与审计" tabindex="-1"><a class="header-anchor" href="#_3-7-日志、监控与审计"><span>3.7 日志、监控与审计</span></a></h3><p><strong>作用</strong>：<br> API 级别的可观测性和合规审计。</p><p><strong>监控指标</strong>：</p><ul><li>QPS / TPS</li><li>P99 / P95 延迟</li><li>错误率</li><li>熔断 / 限流触发次数</li></ul><p><strong>日志内容</strong>：</p><ul><li>请求路径</li><li>用户标识</li><li>响应状态</li><li>耗时</li></ul><hr><h2 id="_4-技术选型" tabindex="-1"><a class="header-anchor" href="#_4-技术选型"><span>4. 技术选型</span></a></h2><table><thead><tr><th>能力</th><th>技术 / 产品</th></tr></thead><tbody><tr><td>API 网关</td><td>Kong、Apigee、Tyk</td></tr><tr><td>高性能代理</td><td>Nginx + Lua、Envoy</td></tr><tr><td>服务网格集成</td><td>Istio Ingress Gateway</td></tr><tr><td>鉴权</td><td>OAuth2、JWT、Keycloak</td></tr><tr><td>限流熔断</td><td>Envoy、Istio、Resilience4j</td></tr></tbody></table><hr><h2 id="_5-架构文本图-api-网关层" tabindex="-1"><a class="header-anchor" href="#_5-架构文本图-api-网关层"><span>5. 架构文本图（API 网关层）</span></a></h2><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>来自接入层流量</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>▼</span></span>
<span class="line"><span>┌─────────────────────────────┐</span></span>
<span class="line"><span>│ API 网关 │</span></span>
<span class="line"><span>│ ────────────────────────── │</span></span>
<span class="line"><span>│ • 路由 &amp; 版本管理 │</span></span>
<span class="line"><span>│ • 认证 / 鉴权 │</span></span>
<span class="line"><span>│ • 限流 / 熔断 / 降级 │</span></span>
<span class="line"><span>│ • 协议 &amp; 数据转换 │</span></span>
<span class="line"><span>│ • 灰度发布 / A/B Test │</span></span>
<span class="line"><span>│ • 日志 / 指标 / 审计 │</span></span>
<span class="line"><span>└─────────────────────────────┘</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>▼</span></span>
<span class="line"><span>应用层（微服务）</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="_6-cto-级设计权衡" tabindex="-1"><a class="header-anchor" href="#_6-cto-级设计权衡"><span>6. CTO 级设计权衡</span></a></h2><ol><li><p><strong>API 网关 ≠ 业务层</strong></p><ul><li>只做治理，不写业务逻辑</li></ul></li><li><p><strong>性能 vs 功能</strong></p><ul><li>网关是高 QPS 组件，功能必须克制</li></ul></li><li><p><strong>集中治理 vs 单点风险</strong></p><ul><li>网关必须集群化、无状态</li></ul></li><li><p><strong>与 Service Mesh 的边界</strong></p><ul><li>外部流量：API 网关</li><li>内部服务：Service Mesh</li></ul></li><li><p><strong>可演进性</strong></p><ul><li>初期：Nginx / Kong</li><li>成熟期：Envoy + Istio</li></ul></li></ol><hr><h2 id="_7-常见错误设计-反例" tabindex="-1"><a class="header-anchor" href="#_7-常见错误设计-反例"><span>7. 常见错误设计（反例）</span></a></h2><ul><li>在网关中实现复杂业务逻辑</li><li>把网关当成 BFF 滥用</li><li>没有限流策略直接暴露服务</li><li>网关无监控，出问题无法定位</li></ul><hr><blockquote><p><strong>一句 CTO 总结</strong>：<br> API 网关是“系统的交通警察”，不是“业务开发者”。</p></blockquote>`,74)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};